 this.bindViewer();this.$('#tech-report-language').value=this.project.language||'tr';const hash=this.alternative.technical?.modelHash;this.$('#tech-model').value=this.models.some(f=>f.hash===hash)?hash:this.models[0].hash;const right=this.alternative.technical?.rightHash;if(this.models.some(f=>f.hash===right))this.$('#tech-right-model').value=right;await this.loadModels();
