 async fetchMesh(file){const cached=await Attachments.meshGet(file.hash);if(MoldPlan.validMesh(cached)&&cached.suggestions?.method==='spatial-axis-rays-v2')return cached;const blob=await this.options.readFile(file),response=await fetch('/api/mesh?filename='+encodeURIComponent(file.name),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:blob});const mesh=await response.json();if(!response.ok||!MoldPlan.validMesh(mesh))throw new Error(mesh.error||'Mesh verisi okunamadı.');await Attachments.meshPut(file.hash,mesh);return mesh;}
 async loadModels(){if(this.busy)return;this.stopMotion();this.busy=true;this.$('#tech-loading').hidden=false;this.$('#tech-loading').textContent='STEP üçgen ağı ve yön önerileri hazırlanıyor…';this.$('#tech-apply').disabled=true;for(const id of ['#tech-model','#tech-right-model'])this.$(id).disabled=true;try{const primary=this.models.find(f=>f.hash===this.$('#tech-model').value);this.mesh=await this.fetchMesh(primary);if(this.closed)return;const right=this.models.find(f=>f.hash===this.$('#tech-right-model').value);this.rightMesh=right?await this.fetchMesh(right):null;if(this.closed)return;const old=this.state;this.state=MoldPlan.initial(this.mesh,this.alternative.technical?.modelHash===primary.hash?this.alternative:{...this.alternative,technical:undefined});if(old&&old.modelHash===primary.hash)this.state={...old};this.state.modelHash=primary.hash;this.state.rightHash=right?.hash||'';for(const c of this.state.cores)if(c.stroke==null)c.stroke=CoreMotion.suggestStroke(this.mesh,this.state,c);this.state.sideMode=true;this.comparisonBase=MoldPlan.calculate(this.planningMesh(),this.state,this.alternative.cavities);this.selected=null;this.points=[];this.renderFields();this.renderQuickPanel();this.rebuild();this.fit();this.$('#tech-loading').hidden=true;this.$('#tech-model-info').textContent=`${this.mesh.triangles.length/3} üçgen · ${this.mesh.faces.length} yüz · ${this.mesh.solids} katı · ${fixed(this.mesh.volume/1000)} cm³ · Görüntüleme toleransı ${fixed(this.mesh.tolerance)} mm`;this.status('Model hazır. Yön ve maça önerilerini inceleyin.');}catch(error){if(!this.closed)this.error(error.message);}finally{this.busy=false;if(!this.closed)for(const id of ['#tech-model','#tech-right-model'])this.$(id).disabled=false;}}
